			{
				Name: aws.String("status"),
				Values: []*string{
					aws.String("completed"),
				},
			},
		},
	}
	describeSnapshotsOutput, err := ec2Svc.DescribeSnapshots(context.TODO(), describeSnapshotsInput)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Group snapshots by backup type
	snapshotsByType := map[string][]*ec2.SnapshotSummary{}
	for _, snapshot := range describeSnapshotsOutput.Snapshots {
		tag, ok := getTagValue(*snapshot, "backup_type")
		if !ok {
			log.Println("Skipping snapshot without backup_type tag:", *snapshot.SnapshotId)
			continue
		}
		snapshotsByType[tag] = append(snapshotsByType[tag], snapshot)
	}

	// Delete snapshots based on type
	for tag, snapshots := range snapshotsByType {
		switch tag {
		case "monthly":
