						   deleteSnapshots(snapshots, ec2Svc, 14)
		case "daily":
			// Keep last 10 daily snapshots
						   deleteSnapshots(snapshots, ec2Svc, 10)
		case "weekly":
			// Keep last 4 weekly snapshots
						   deleteSnapshots(snapshots, ec2Svc, 4)
		case "yearly":
			// Keep last 1 yearly snapshot
						   deleteSnapshots(snapshots, ec2Svc, 1)
		}
	}

	return nil, nil
}

func getTagValue(snapshot ec2.Snapshot, key string) (string, bool) {
	for _, tag := range snapshot.Tags {
		if *tag.Key == key {
			return *tag.Value, true
		}
	}
	return "", false
}

func deleteSnapshots(snapshots []*ec2.SnapshotSummary, ec2Svc *ec2.EC2, numToKeep int) {
